import java.util.*;

class Solution {
    public int fuseCost(int[] piles, int k) {
        int n = piles.length;
        if ((n - 1) % (k - 1) != 0) return -1;         // each move removes exactly k-1 piles
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + piles[i];
        int[][] dp = new int[n][n];                    // dp[i][j]: squeeze i..j as much as possible
        for (int len = k; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1, best = Integer.MAX_VALUE;
                for (int m = i; m < j; m += k - 1) {   // left part i..m collapses to one pile
                    best = Math.min(best, dp[i][m] + dp[m + 1][j]);
                }
                if ((j - i) % (k - 1) == 0) best += pre[j + 1] - pre[i];  // final fuse into one pile
                dp[i][j] = best;
            }
        }
        return dp[0][n - 1];
    }
}

