class Solution:
    def fuseCost(self, piles: List[int], k: int) -> int:
        n = len(piles)
        if (n - 1) % (k - 1): return -1
        pre = [0]
        for x in piles: pre.append(pre[-1] + x)
        dp = [[0] * n for _ in range(n)]
        for length in range(k, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp[i][j] = min(dp[i][m] + dp[m + 1][j] for m in range(i, j, k - 1))
                if (j - i) % (k - 1) == 0:
                    dp[i][j] += pre[j + 1] - pre[i]
        return dp[0][n - 1]

