function fuseCost(piles, k) {
  const n = piles.length;
  if ((n - 1) % (k - 1) !== 0) return -1;
  const pre = [0]; for (const x of piles) pre.push(pre[pre.length - 1] + x);
  const INF = 1e18;
  // f[i][j][p] = min cost to turn piles i..j into p piles
  const f = Array.from({length: n}, () => Array.from({length: n}, () => new Array(k + 1).fill(INF)));
  for (let i = 0; i < n; i++) f[i][i][1] = 0;
  for (let len = 2; len <= n; len++) for (let i = 0; i + len - 1 < n; i++) {
    const j = i + len - 1;
    for (let p = 2; p <= k; p++)
      for (let m = i; m < j; m++) {
        const a = f[i][m][1], b = f[m+1][j][p-1];
        if (a < INF && b < INF) f[i][j][p] = Math.min(f[i][j][p], a + b);
      }
    if (f[i][j][k] < INF) f[i][j][1] = f[i][j][k] + pre[j+1] - pre[i];
  }
  return f[0][n-1][1];
}
